const body = $json.body || $json;
let files;
if (body.files && Array.isArray(body.files)) {
  files = body.files;
} else if (body.storagePath) {
  files = [{ fileName: body.fileName || 'document.pdf', storagePath: body.storagePath }];
} else {
  throw new Error('Input invalide: files array ou storagePath requis');
}
if (files.length > 10) {
  throw new Error('Maximum 10 fichiers par batch. Recu: ' + files.length);
}
return files.map(f => ({
  json: { fileName: f.fileName, storagePath: f.storagePath, startTime: Date.now() }
}));

const signedPath = $json.signedURL;
if (!signedPath) throw new Error('Signed URL vide');
const fullUrl = 'https://{ANON_SUPABASE_REF}.supabase.co/storage/v1' + signedPath;
const loopItem = $('Loop Fichiers').first().json;
return [{ json: { pdfUrl: fullUrl, storagePath: loopItem.storagePath, fileName: loopItem.fileName, startTime: loopItem.startTime } }];

const item = $input.first();
const loopItem = $('Loop Fichiers').first().json;
const content = item.json.content?.[0]?.text || '';
let jsonStr = content.trim();
const codeMatch = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
if (codeMatch) jsonStr = codeMatch[1].trim();
if (!jsonStr.startsWith('{')) {
  const objMatch = jsonStr.match(/\{[\s\S]*\}/);
  if (objMatch) jsonStr = objMatch[0];
}
jsonStr = jsonStr.replace(/([,{\n]\s*)([a-zA-Z_][a-zA-Z0-9_]*)(\s*"?\s*:)/g, '$1"$2"$3');
jsonStr = jsonStr.replace(/""([^"]+)""/g, '"$1"');
const parsed = JSON.parse(jsonStr);
if (!parsed.type_document) throw new Error('type_document manquant');
if (!parsed.reference) throw new Error('reference manquante');
if (!parsed.entreprise_nom) throw new Error('entreprise_nom manquant');
if (!['offre', 'commande'].includes(parsed.type_document)) throw new Error('type_document invalide: ' + parsed.type_document);
return [{ json: { ...parsed, storagePath: loopItem.storagePath || '', fileName: loopItem.fileName || 'document.pdf', dureeMs: Date.now() - (loopItem.startTime || Date.now()) } }];

// Fusionne l'entreprise_id (RPC) avec les donnees OCR
const rpcResponse = $input.first().json;
const ocrData = $('Parser et Valider').first().json;

// La RPC retourne un UUID en texte (responseFormat=text)
// $json.data contient la string brute, ex: '"uuid-value"'
let entrepriseId = (rpcResponse.data || '').trim().replace(/^"|"$/g, '');

if (!entrepriseId || entrepriseId.length < 10) {
  throw new Error('upsert_entreprise n\'a pas retourne d\'UUID. Response: ' + JSON.stringify(rpcResponse));
}

return [{
  json: {
    entreprise_id: entrepriseId,
    type_document: ocrData.type_document,
    reference: ocrData.reference,
    reference_offre: ocrData.reference_offre || null,
    numero_client: ocrData.numero_client || null,
    numero_commande_client: ocrData.numero_commande_client || null,
    date_document: ocrData.date_document,
    date_expiration: ocrData.date_expiration || null,
    date_expedition: ocrData.date_expedition || null,
    correspondant: ocrData.correspondant || null,
    lignes: ocrData.lignes || [],
    montant_ht: ocrData.montant_ht || 0,
    montant_ttc: ocrData.montant_ttc || 0,
    conditions_paiement: ocrData.conditions_paiement || null,
    conditions_livraison: ocrData.conditions_livraison || null,
    storagePath: ocrData.storagePath,
    fileName: ocrData.fileName,
    dureeMs: ocrData.dureeMs
  }
}];

// Prepare les donnees pour le log OCR succes
const insertResult = $input.first().json;
const ocrData = $('Parser et Valider').first().json;

// HTTP Request PostgREST returns array with return=representation
const record = Array.isArray(insertResult) ? insertResult[0] : insertResult;

return [{
  json: {
    fichier_source: ocrData.storagePath || '',
    type_document: ocrData.type_document,
    statut: 'success',
    donnees_extraites: JSON.stringify(ocrData),
    erreurs: null,
    score_confiance: 0.95,
    record_id: record?.id || null,
    duree_ms: ocrData.dureeMs || 0
  }
}];

const data = $input.first().json;
let storagePath = 'unknown';
try { storagePath = $('Loop Fichiers').first().json.storagePath || 'unknown'; } catch(e) {}

// Deep extract error message from various n8n error formats
let errorMsg = 'Unknown error';
if (typeof data.error === 'string') {
  errorMsg = data.error;
} else if (typeof data.message === 'string') {
  errorMsg = data.message;
} else if (data.error?.message) {
  errorMsg = data.error.message;
} else if (data.error) {
  errorMsg = JSON.stringify(data.error).substring(0, 500);
} else {
  errorMsg = JSON.stringify(data).substring(0, 500);
}

return [{ json: {
  fichier_source: storagePath,
  type_document: data.type_document || 'unknown',
  statut: 'failed',
  donnees_extraites: JSON.stringify({ error: errorMsg, keys: Object.keys(data) }),
  erreurs: [errorMsg],
  score_confiance: 0, record_id: null, duree_ms: 0
} }];

